insert into research_item (jurisdiction_code, item, status, detail, where_to_get, checked_on) values ('DE', 'wealth:trusts_count', 'blocked', 'Germany: The Transparency Register (Bundesanzeiger) counts entries per legal form; the latest official count found (Bundestag Drucksache 20/3221, 17 Aug 2022) has a row for trusts, but its table does not read reliably as text, so no figure is stored.', 'Bundestag Drucksache 20/3221 (https://dserver.bundestag.de/btd/20/032/2003221.pdf), answer 2: the number for "TR-Trust"; or a newer government answer. Tell Claude the number and its date.', '2026-10-03') on conflict (jurisdiction_code, item) do update set status = excluded.status, detail = excluded.detail, where_to_get = excluded.where_to_get, checked_on = excluded.checked_on;
